using Microsoft.Playwright;
using System.Text.RegularExpressions;
namespace BARANG.Backoffice.E2ETests;

public sealed class DeployedInteractivityTests : IAsyncLifetime
{
    private static readonly string[] Languages = ["فارسی", "العربية", "English"];
    private IPlaywright playwright = null!; private IBrowser browser = null!; private IBrowserContext context = null!; private IPage page = null!; private BrowserDiagnostics diagnostics = null!; private readonly string baseUrl = Environment.GetEnvironmentVariable("BARANG_E2E_BASE_URL") ?? "http://localhost:5100";
    public async ValueTask InitializeAsync() { string username = Environment.GetEnvironmentVariable("BARANG_E2E_USERNAME") ?? throw new InvalidOperationException("BARANG_E2E_USERNAME is required."); string password = Environment.GetEnvironmentVariable("BARANG_E2E_PASSWORD") ?? throw new InvalidOperationException("BARANG_E2E_PASSWORD is required."); string? executable = Environment.GetEnvironmentVariable("BARANG_E2E_BROWSER_PATH"); playwright = await Playwright.CreateAsync(); browser = await playwright.Chromium.LaunchAsync(new() { Headless = true, ExecutablePath = executable }); context = await browser.NewContextAsync(new() { Locale = "en-US" }); page = await context.NewPageAsync(); diagnostics = new(page); diagnostics.Attach(); await page.GotoAsync($"{baseUrl}/login", new() { WaitUntil = WaitUntilState.NetworkIdle }); await page.Locator("#username").FillAsync(username); await page.Locator("#password").FillAsync(password); await page.Locator("button[type=submit]").ClickAsync(); await page.WaitForLoadStateAsync(LoadState.NetworkIdle); if (new Uri(page.Url).AbsolutePath == "/company") { string? company = Environment.GetEnvironmentVariable("BARANG_E2E_COMPANY_ID"); ILocator choice = string.IsNullOrWhiteSpace(company) ? page.Locator(".company-list form button[type=submit]").First : page.Locator($".company-list form:has(input[name='companyId'][value='{company}']) button[type=submit]"); await choice.ClickAsync(); await page.WaitForLoadStateAsync(LoadState.NetworkIdle); } Assert.DoesNotContain("/login", page.Url, StringComparison.OrdinalIgnoreCase); }
    public async ValueTask DisposeAsync() { diagnostics?.Dump("browser diagnostics"); if (context is not null) await context.DisposeAsync(); if (browser is not null) await browser.DisposeAsync(); playwright?.Dispose(); }
    [Fact] public async Task PersonsNewRealBrowserAllocatesTheNextNumericCode() { await NavigateViaMenu("/master/persons"); await AssertCircuit(); ILocator button = page.Locator("header.crud-header button.btn-primary"); string hit = await HitTest(button); string buttonHtml = await button.EvaluateAsync<string>("el=>el.outerHTML"); string before = await page.Locator("body").InnerHTMLAsync(); string beforeUrl = page.Url; await button.ClickAsync(); await page.WaitForTimeoutAsync(500); ILocator dialog = page.Locator(".dialog-backdrop .crud-dialog"); bool visible = await dialog.IsVisibleAsync(); string after = await page.Locator("body").InnerHTMLAsync(); Assert.True(visible, $"Persons New click did not expose its create UI. URL {beforeUrl} -> {page.Url}; DOM changed={before != after}; dialog count={await dialog.CountAsync()}; hit={hit}; button={buttonHtml}; events={string.Join(" | ", diagnostics.Events)}"); Assert.Equal("dialog", await dialog.GetAttributeAsync("role")); var box = await dialog.BoundingBoxAsync(); Assert.NotNull(box); Assert.InRange(Math.Abs(box.X + box.Width / 2 - page.ViewportSize!.Width / 2d), 0, 2); Assert.Equal(0, await dialog.Locator("header .barang-icon-button").CountAsync()); string marker = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString(System.Globalization.CultureInfo.InvariantCulture); await dialog.Locator(".crud-form input:not([disabled])").Nth(0).FillAsync("Sequence"); await dialog.Locator(".crud-form input:not([disabled])").Nth(1).FillAsync(marker); await dialog.Locator("footer button.btn-primary").ClickAsync(); await Assertions.Expect(dialog).ToBeHiddenAsync(new() { Timeout = 15000 }); ILocator search = page.Locator(".crud-toolbar .search-box input"); await search.FillAsync(marker); await search.PressAsync("End"); await page.WaitForTimeoutAsync(500); ILocator created = page.Locator("table.data-grid tbody tr").Filter(new() { HasText = marker }); await Assertions.Expect(created).ToBeVisibleAsync(); string code = (await created.Locator(".code-pill").InnerTextAsync()).Trim(); Assert.Matches(new Regex("^[1-9][0-9]*$"), code); }
    [Fact] public async Task PersonsEditTabsJalaliPickerAndCancelAreRealBrowserInteractive() { await page.GotoAsync($"{baseUrl}/culture?culture=fa&returnUrl=%2Fmaster%2Fpersons", new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator edit = page.Locator("table.data-grid tbody .barang-icon-button").Filter(new() { Has = page.Locator("svg[data-icon='edit']") }).First; await edit.ClickAsync(); ILocator dialog = page.Locator(".barang-modal.modal-large"); await Assertions.Expect(dialog).ToBeVisibleAsync(); await dialog.Locator(".tabs button").First.WaitForAsync(); Assert.Equal(4, await dialog.Locator(".tabs button").CountAsync()); Assert.Equal(0, await dialog.Locator("header .barang-icon-button").CountAsync()); foreach (ILocator tab in await dialog.Locator(".tabs button").AllAsync()) { await tab.ClickAsync(); await Assertions.Expect(tab).ToHaveClassAsync("active"); } await dialog.Locator(".tabs button").First.ClickAsync(); await dialog.Locator(".locale-date-input .date-picker-button").ClickAsync(); ILocator calendar = dialog.Locator(".locale-calendar[role=dialog]"); await Assertions.Expect(calendar).ToBeVisibleAsync(); await Assertions.Expect(calendar.Locator(".calendar-period-button")).ToHaveCountAsync(2); await calendar.Locator(".calendar-period-button").Nth(1).ClickAsync(); await Assertions.Expect(calendar.Locator(".calendar-years button")).ToHaveCountAsync(12); await calendar.Locator(".calendar-years button").Nth(5).ClickAsync(); await Assertions.Expect(calendar.Locator(".calendar-months button")).ToHaveCountAsync(12); await calendar.Locator(".calendar-months button").Nth(2).ClickAsync(); await Assertions.Expect(calendar.Locator(".calendar-days button")).ToHaveCountAsync(42); await calendar.Locator(".calendar-days button").First.FocusAsync(); await page.Keyboard.PressAsync("Escape"); await Assertions.Expect(calendar).ToBeHiddenAsync(); ILocator firstName = dialog.Locator(".crud-form input:not([disabled])").First; string original = await firstName.InputValueAsync(); await firstName.FillAsync(original + " unsaved"); await dialog.Locator(".crud-form footer .btn-secondary").ClickAsync(); ILocator discard = page.Locator(".barang-modal.modal-small"); await Assertions.Expect(discard).ToBeVisibleAsync(); await discard.Locator("footer .btn-danger").ClickAsync(); await Assertions.Expect(dialog).ToBeHiddenAsync(); await Assertions.Expect(page.Locator("table.data-grid")).ToBeVisibleAsync(); }
    [Fact] public async Task OrganizationalChartRealBrowserNodeActionsMutateUI() { await NavigateViaMenu("/master/organization-chart"); await AssertCircuit(); ILocator company = page.Locator("article.company-node").First; await company.WaitForAsync(); ILocator expander = company.Locator("button.org-expander"); string before = await expander.GetAttributeAsync("aria-expanded") ?? "false"; await HitTest(expander); await expander.ClickAsync(); await Assertions.Expect(expander).Not.ToHaveAttributeAsync("aria-expanded", before); await Assertions.Expect(expander.Locator($"svg[data-icon='{(before == "false" ? "chevron-down" : "chevron-right")}']")).ToBeVisibleAsync(); ILocator view = company.Locator("[data-chart-action='company-view']"); await view.ClickAsync(); ILocator dialog = page.Locator(".dialog-backdrop .crud-dialog"); await Assertions.Expect(dialog).ToBeVisibleAsync(); await dialog.Locator("button.dialog-close").ClickAsync(); await Assertions.Expect(dialog).ToBeHiddenAsync(); ILocator addBranch = company.Locator("[data-chart-action='branch-create']"); await addBranch.ClickAsync(); await Assertions.Expect(dialog).ToBeVisibleAsync(); await Assertions.Expect(dialog.Locator("input").First).ToBeEditableAsync(); }
    [Fact] public async Task OrganizationalChartAddPersonRealBrowserClickOpensSearchableAssignment() { string marker = "ChartCandidate" + DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString(System.Globalization.CultureInfo.InvariantCulture); await NavigateViaMenu("/master/persons"); await page.Locator("header.crud-header button.btn-primary").ClickAsync(); ILocator personDialog = page.Locator(".dialog-backdrop .crud-dialog"); await personDialog.Locator(".crud-form input:not([disabled])").Nth(0).FillAsync(marker); await personDialog.Locator(".crud-form input:not([disabled])").Nth(1).FillAsync("Person"); await personDialog.Locator("footer button.btn-primary").ClickAsync(); await Assertions.Expect(personDialog).ToBeHiddenAsync(new() { Timeout = 15000 }); await NavigateViaMenu("/master/organization-chart"); ILocator company = page.Locator("article.company-node").First; await EnsureExpanded(company); ILocator branch = page.Locator("article.branch-node").First; await branch.WaitForAsync(); await EnsureExpanded(branch); ILocator unit = page.Locator("article.unit-node").First; await unit.WaitForAsync(); ILocator addPerson = unit.Locator("[data-chart-action='assignment-create']"); await addPerson.ClickAsync(); ILocator dialog = page.Locator(".dialog-backdrop .crud-dialog"); await Assertions.Expect(dialog).ToBeVisibleAsync(); ILocator personSearch = dialog.Locator(".searchable-select input").First; await personSearch.FillAsync(marker); await page.WaitForTimeoutAsync(400); await Assertions.Expect(dialog.Locator("[role=listbox]")).ToBeVisibleAsync(); Assert.True(await dialog.Locator("[role=option]").CountAsync() > 0, "Person search returned no real candidates."); }
    [Theory][InlineData("fa", "rtl")][InlineData("en", "ltr")][InlineData("ar", "rtl")] public async Task PersonsAndChartSwitchRealBrowserLanguageAndDirection(string culture, string direction) { await page.GotoAsync($"{baseUrl}/culture?culture={culture}&returnUrl=%2Fmaster%2Fpersons", new() { WaitUntil = WaitUntilState.NetworkIdle }); Assert.Equal(direction, await page.Locator("html").GetAttributeAsync("dir")); await page.Locator("header.crud-header h1").WaitForAsync(); await page.GotoAsync($"{baseUrl}/culture?culture={culture}&returnUrl=%2Fmaster%2Forganization-chart", new() { WaitUntil = WaitUntilState.NetworkIdle }); Assert.Equal(direction, await page.Locator("html").GetAttributeAsync("dir")); await page.Locator("main h1").WaitForAsync(); }
    [Fact] public async Task GlobalDesignSystemShellUsesLoginPaletteAndRemainsCompactResponsive() { await page.GotoAsync($"{baseUrl}/culture?culture=en&returnUrl=%2F", new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator sidebar = page.Locator("aside.sidebar"); await sidebar.WaitForAsync(); Assert.Equal("rgb(52, 36, 100)", await sidebar.EvaluateAsync<string>("el=>getComputedStyle(el).backgroundColor")); float width = await sidebar.EvaluateAsync<float>("el=>el.getBoundingClientRect().width"); Assert.InRange(width, 240, 265); await Assertions.Expect(page.Locator("a.home-shortcut").First).ToBeVisibleAsync(); Assert.Equal(Languages, await page.Locator(".language-switch a").AllInnerTextsAsync()); await Assertions.Expect(page.Locator(".sidebar-account")).ToBeVisibleAsync(); Assert.DoesNotContain("Workspace", await page.Locator(".sidebar-navigation").InnerTextAsync(), StringComparison.OrdinalIgnoreCase); Assert.Equal(0, await page.Locator(".sidebar-collapse-toggle, .mobile-sidebar-toggle, .sidebar-expand-toggle, .mobile-nav-toggle, .topbar-leading, .shell-location").CountAsync()); await page.SetViewportSizeAsync(390, 844); ILocator toggle = page.Locator("button.mobile-navigation-trigger"); await Assertions.Expect(toggle).ToBeVisibleAsync(); await toggle.ClickAsync(); await Assertions.Expect(page.Locator(".shell")).ToHaveClassAsync(new Regex("navigation-open")); await Assertions.Expect(sidebar).ToBeInViewportAsync(); bool overflow = await page.Locator("body").EvaluateAsync<bool>("el=>el.scrollWidth>el.clientWidth+1"); Assert.False(overflow, "The responsive shell introduced horizontal page overflow."); }
    [Theory][InlineData("fa", "rtl", "^سلام، .+$")][InlineData("ar", "rtl", "^مرحباً، .+$")][InlineData("en", "ltr", "^Hello, .+$")] public async Task GlobalLanguageSwitchUpdatesLocalizedShellAndDirection(string culture, string direction, string greetingPattern) { await page.GotoAsync($"{baseUrl}/culture?culture={culture}&returnUrl=%2F", new() { WaitUntil = WaitUntilState.NetworkIdle }); Assert.Equal(culture, await page.Locator("html").GetAttributeAsync("lang")); Assert.Equal(direction, await page.Locator("html").GetAttributeAsync("dir")); await Assertions.Expect(page.Locator("main h1")).ToHaveTextAsync(new Regex(greetingPattern)); await Assertions.Expect(page.Locator($".language-switch a[hreflang='{culture}']")).ToHaveClassAsync(new Regex("selected")); Assert.Equal(Languages, await page.Locator(".language-switch a").AllInnerTextsAsync()); }
    [Fact] public async Task CompanySelectorSubmitsChangesContextAndCloses() { await page.GotoAsync($"{baseUrl}/culture?culture=en&returnUrl=%2Fcompany", new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator options = page.Locator("button.company-option[type='submit']"); Assert.True(await options.CountAsync() > 0, "No selectable company was exposed and no selection flow could be validated."); ILocator choice = options.First; string selected = (await choice.Locator("strong").InnerTextAsync()).Trim(); await choice.ClickAsync(); await page.WaitForURLAsync(url => !new Uri(url).AbsolutePath.Equals("/company", StringComparison.OrdinalIgnoreCase)); await page.WaitForLoadStateAsync(LoadState.NetworkIdle); await Assertions.Expect(page.Locator(".company-chip strong")).ToHaveTextAsync(selected); await page.GotoAsync($"{baseUrl}/master/persons", new() { WaitUntil = WaitUntilState.NetworkIdle }); await Assertions.Expect(page.Locator("main#main-content")).ToBeVisibleAsync(); }
    [Fact] public async Task SharedSortHeadersUserGridAndActionIconsMatchTheGlobalStandard() { await page.SetViewportSizeAsync(1366, 768); await page.GotoAsync($"{baseUrl}/culture?culture=en&returnUrl=%2Fmanage%2Fcustomers", new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator sort = page.Locator(".barang-sort-header").First; await Assertions.Expect(sort).ToBeVisibleAsync(); Assert.Equal("0px", await sort.EvaluateAsync<string>("el=>getComputedStyle(el).borderTopWidth")); Assert.Equal("rgba(0, 0, 0, 0)", await sort.EvaluateAsync<string>("el=>getComputedStyle(el).backgroundColor")); await sort.ClickAsync(); await Assertions.Expect(sort).ToHaveClassAsync(new Regex("active")); Assert.Equal(1, await sort.Locator("svg[data-icon='arrow-up'],svg[data-icon='arrow-down']").CountAsync()); await page.GotoAsync($"{baseUrl}/admin/user-access", new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator wrapper = page.Locator(".uam-users-grid-wrap"); await Assertions.Expect(wrapper).ToBeVisibleAsync(); bool overflow = await wrapper.EvaluateAsync<bool>("el=>el.scrollWidth>el.clientWidth+1"); Assert.False(overflow, "Users DataGrid horizontally overflowed at a normal desktop width."); ILocator menu = page.Locator(".uam-users-grid .barang-action-menu-trigger").First; await Assertions.Expect(menu).ToBeVisibleAsync(); Assert.Equal(await menu.GetAttributeAsync("title"), await menu.GetAttributeAsync("aria-label")); var box = await menu.BoundingBoxAsync(); Assert.NotNull(box); Assert.InRange(box.Width, 34, 38); Assert.InRange(box.Height, 34, 38); var glyph = await menu.Locator("svg").BoundingBoxAsync(); Assert.NotNull(glyph); Assert.InRange(glyph.Width, 17, 19); Assert.InRange(glyph.Height, 17, 19); await menu.ClickAsync(); await Assertions.Expect(page.Locator(".barang-action-menu-popup").First).ToBeVisibleAsync(); }

    [Fact] public async Task AuditPageRendersAuthorizedReadableFiltersAndRowsOrEmptyState() { await page.GotoAsync($"{baseUrl}/culture?culture=en&returnUrl=%2Fworkspace%2Faudit", new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator audit = page.Locator(".audit-page"); await Assertions.Expect(audit).ToBeVisibleAsync(); await Assertions.Expect(audit.Locator(".audit-filters input").First).ToBeVisibleAsync(); await Assertions.Expect(audit.Locator(".audit-filters input").Nth(1)).ToBeVisibleAsync(); Assert.True(await audit.Locator(".audit-grid").CountAsync() == 1 || await audit.Locator(".state-box").CountAsync() == 1, "Audit must render a readable table or a localized empty state."); Assert.Equal(0, await page.Locator("#blazor-error-ui").CountAsync()); }
    [Theory]
    [InlineData("fa", "rtl")]
    [InlineData("ar", "rtl")]
    [InlineData("en", "ltr")]
    public async Task SharedActionMenuItemsKeepIconAndLabelOnOneHorizontalRow(string culture, string direction)
    {
        await page.GotoAsync($"{baseUrl}/culture?culture={culture}&returnUrl=%2Fmanage%2Fcustomers", new() { WaitUntil = WaitUntilState.NetworkIdle });
        Assert.Equal(direction, await page.Locator("html").GetAttributeAsync("dir"));
        ILocator trigger = page.Locator("table.data-grid .barang-action-menu-trigger").First;
        await Assertions.Expect(trigger).ToBeVisibleAsync();
        await trigger.ClickAsync();
        ILocator item = page.Locator(".barang-action-menu-popup .barang-icon-button").First;
        await Assertions.Expect(item).ToBeVisibleAsync();
        ILocator label = item.Locator(".barang-action-menu-item-label");
        ILocator icon = item.Locator("svg");
        string[] values = await item.EvaluateAsync<string[]>("el => { const s=getComputedStyle(el); return [s.display,s.flexDirection,s.alignItems,s.gap,s.width,s.borderTopWidth,s.boxShadow,s.direction]; }");
        Assert.Equal("flex", values[0]);
        Assert.Equal("row", values[1]);
        Assert.Equal("center", values[2]);
        Assert.Equal("8px", values[3]);
        Assert.Equal("0px", values[5]);
        Assert.Equal("none", values[6]);
        Assert.Equal(direction, values[7]);
        var itemBox = await item.BoundingBoxAsync();
        var iconBox = await icon.BoundingBoxAsync();
        var labelBox = await label.BoundingBoxAsync();
        Assert.NotNull(itemBox); Assert.NotNull(iconBox); Assert.NotNull(labelBox);
        Assert.InRange(Math.Abs((iconBox!.Y + iconBox.Height / 2) - (labelBox!.Y + labelBox.Height / 2)), 0, 1);
        Assert.True(direction == "rtl" ? iconBox.X > labelBox.X : iconBox.X < labelBox.X);
        await page.ScreenshotAsync(new() { Path = Path.Combine(Environment.GetEnvironmentVariable("BARANG_E2E_ARTIFACTS") ?? ".artifacts", $"step45-action-menu-{culture}.png"), FullPage = true });
    }
    [Fact] public async Task EveryExposedNavigationPageRendersTheSharedShellWithoutRuntimeFailure() { await page.GotoAsync($"{baseUrl}/culture?culture=en&returnUrl=%2F", new() { WaitUntil = WaitUntilState.NetworkIdle }); string[] routes = await page.Locator(".sidebar-navigation a[href]").EvaluateAllAsync<string[]>("links=>[...new Set(links.map(link=>link.getAttribute('href')).filter(href=>href&&href!='/'))]"); Assert.True(routes.Length >= 25, $"Expected at least 25 permission-visible Backoffice routes, found {routes.Length}."); foreach (string route in routes) { await page.GotoAsync($"{baseUrl}{route}", new() { WaitUntil = WaitUntilState.NetworkIdle }); Assert.DoesNotContain("/login", page.Url, StringComparison.OrdinalIgnoreCase); await Assertions.Expect(page.Locator("aside.sidebar")).ToBeVisibleAsync(); await Assertions.Expect(page.Locator("main#main-content")).ToBeVisibleAsync(); Assert.True(await page.Locator("main h1").CountAsync() > 0, $"Route {route} has no page heading."); await Assertions.Expect(page.Locator("#blazor-error-ui")).ToBeHiddenAsync(); Assert.Equal(0, await page.Locator(".blazor-error-boundary").CountAsync()); string text = await page.Locator("main#main-content").InnerTextAsync(); Assert.DoesNotMatch(new Regex(@"\b(?:Nav|Module|Description|Action|Admin)_[A-Za-z0-9_-]+\b"), text); bool overflow = await page.Locator("body").EvaluateAsync<bool>("el=>el.scrollWidth>el.clientWidth+1"); Assert.False(overflow, $"Route {route} introduced horizontal page overflow."); } }
    private async Task AssertCircuit() { await page.WaitForTimeoutAsync(1000); Assert.Contains(diagnostics.Events, x => x.Contains("websocket: opened", StringComparison.OrdinalIgnoreCase) && x.Contains("/_blazor", StringComparison.OrdinalIgnoreCase)); }
    private async Task NavigateViaMenu(string path) { await page.GotoAsync(baseUrl, new() { WaitUntil = WaitUntilState.NetworkIdle }); ILocator link = page.Locator($"nav a[href='{path}']"); ILocator group = link.Locator("xpath=ancestor::details[1]"); if (await group.CountAsync() > 0 && !await group.EvaluateAsync<bool>("el=>el.open")) { await group.Locator("summary").ClickAsync(); await Assertions.Expect(link).ToBeVisibleAsync(); } await link.ClickAsync(); await page.WaitForURLAsync($"**{path}"); await page.WaitForLoadStateAsync(LoadState.NetworkIdle); }
    private static async Task EnsureExpanded(ILocator node) { ILocator expander = node.Locator("button.org-expander"); if (string.Equals(await expander.GetAttributeAsync("aria-expanded"), "false", StringComparison.OrdinalIgnoreCase)) await expander.ClickAsync(); }
    private static async Task<string> HitTest(ILocator locator) { await locator.ScrollIntoViewIfNeededAsync(); object? result = await locator.EvaluateAsync<object>("el => { const r=el.getBoundingClientRect(); const hit=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2); return { expected:el.tagName, actual:hit?.tagName, actualClass:hit?.className, same:hit===el || el.contains(hit), disabled:el.disabled, pointer:getComputedStyle(el).pointerEvents }; }"); return System.Text.Json.JsonSerializer.Serialize(result); }
}
